SELECT 
FROM sys_parameter_value AS values_table
LEFT JOIN org_organization AS organizations ON organizations.id = values_table.organization_id
WHERE values_table.parameter_key = #{key}
  AND values_table.environment_code = #{environment}


        AND values_table.organization_id = #{organizationId}


        AND values_table.organization_id IS NULL

INSERT INTO sys_parameter_value (
    parameter_key,    
    value_type,       
    environment_code, 
    organization_id,  
    parameter_value,  
    is_enabled,       
    created_by,       
    updated_by        
) VALUES (
    #{key}, #{valueType}, #{command.environment}, #{command.organizationId}, #{command.value},
    #{command.enabled}, #{actor}, #{actor}
);
SELECT CONVERT(BIGINT, SCOPE_IDENTITY());

mapper.update:
UPDATE sys_parameter_value
SET value_type = #{valueType}, parameter_value = #{command.value}, is_enabled = #{command.enabled}, updated_by = #{actor}, updated_at = SYSUTCDATETIME()
WHERE id = #{id} AND row_version = #{command.expectedVersion}

