DECLARE @reference_count BIGINT = 0;
DECLARE @reference_sql NVARCHAR(MAX) = N'';
SELECT @reference_sql = @reference_sql
    + N'SELECT @total = @total + COUNT_BIG(1) FROM '
    + QUOTENAME(OBJECT_SCHEMA_NAME(fkc.parent_object_id)) + N'.'
    + QUOTENAME(OBJECT_NAME(fkc.parent_object_id)) + N' WHERE '
    + QUOTENAME(COL_NAME(fkc.parent_object_id, fkc.parent_column_id)) + N' = @item_id;'
FROM sys.foreign_key_columns AS fkc
WHERE fkc.referenced_object_id = OBJECT_ID(N'dbo.sys_dictionary_item')
  AND COL_NAME(fkc.referenced_object_id, fkc.referenced_column_id) = N'id';
IF LEN(@reference_sql) > 0
    EXEC sys.sp_executesql @reference_sql,
        N'@item_id BIGINT, @total BIGINT OUTPUT',
        @item_id = #{itemId}, @total = @reference_count OUTPUT;
SELECT @reference_count;

SELECT endpoints.id, endpoints.external_system_id, endpoints.environment_code, endpoints.organization_id, organizations.organization_code, endpoints.base_url, endpoints.connect_timeout_ms, endpoints.read_timeout_ms, endpoints.credential_reference, CASE WHEN credentials.endpoint_id IS NOT NULL OR endpoints.credential_reference LIKE N'env://%' THEN 1 ELSE 0 END AS credential_configured, endpoints.is_enabled, endpoints.created_at, endpoints.updated_at, endpoints.row_version, endpoints.organization_query_name, endpoints.source_organization_id, endpoints.source_organization_name, endpoints.verification_status, endpoints.verified_at, endpoints.verification_failure_summary FROM sys_external_endpoint AS endpoints LEFT JOIN org_organization AS organizations ON organizations.id = endpoints.organization_id LEFT JOIN sys_external_endpoint_credential AS credentials ON credentials.endpoint_id = endpoints.id WHERE endpoints.external_system_id = #{systemId} AND (endpoints.organization_id IS NULL
OR organizations.organization_code IN
#{code}
) ORDER BY endpoints.environment_code, organizations.organization_code, endpoints.id

SELECT endpoints.id, endpoints.external_system_id, endpoints.environment_code, endpoints.organization_id, organizations.organization_code, endpoints.base_url, endpoints.connect_timeout_ms, endpoints.read_timeout_ms, endpoints.credential_reference, CASE WHEN credentials.endpoint_id IS NOT NULL OR endpoints.credential_reference LIKE N'env://%' THEN 1 ELSE 0 END AS credential_configured, endpoints.is_enabled, endpoints.created_at, endpoints.updated_at, endpoints.row_version, endpoints.organization_query_name, endpoints.source_organization_id, endpoints.source_organization_name, endpoints.verification_status, endpoints.verified_at, endpoints.verification_failure_summary FROM sys_external_endpoint AS endpoints LEFT JOIN org_organization AS organizations ON organizations.id = endpoints.organization_id LEFT JOIN sys_external_endpoint_credential AS credentials ON credentials.endpoint_id = endpoints.id WHERE endpoints.id = #{endpointId}
AND (endpoints.organization_id IS NULL
OR organizations.organization_code IN
#{code}
)


SELECT CASE WHEN EXISTS (
    SELECT 1 FROM sys_external_endpoint
    WHERE external_system_id = #{systemId} AND environment_code = #{environment}
    AND id <> #{excludedEndpointId}
    AND organization_id = #{organizationId}
        AND organization_id IS NULL
) THEN 1 ELSE 0 END

