UPDATE sys_external_endpoint
SET source_organization_id = #{sourceOrganizationId}, source_organization_name = #{sourceOrganizationName}, verification_status = 'VERIFIED', verified_at = SYSUTCDATETIME(), verification_failure_summary = NULL, is_enabled = 1, updated_by = #{actor}, updated_at = SYSUTCDATETIME() WHERE id = #{endpointId}
AND row_version = #{expectedVersion}

UPDATE sys_external_endpoint

SET verification_status = #{verificationStatus}, verified_at = SYSUTCDATETIME(),
    verification_failure_summary = #{failureSummary}, is_enabled = 0,
    updated_by = #{actor}, updated_at = SYSUTCDATETIME()
WHERE id = #{endpointId}

  AND row_version = #{expectedVersion}

